//! The C# bindings of ffx-rust's game-state API (`ffx_state`), generated
//! from its schema: one C# class per struct with a decoder that reads the
//! encoding `Snapshot::encode` writes (ffx-rust's docs/state-api.md).
//!
//! `cargo run -p ffx-state-cs` writes `godot/src/Api/GameStateApi.g.cs`;
//! the test `the_bindings_are_current` fails when the committed file is not
//! what the schema gives (after an ffx-rust update: run the generator).

use std::fmt::Write as _;

use ffx_state::{StructSchema, Ty};

/// Where the generated file goes, from the repository's root.
pub const OUTPUT: &str = "godot/src/Api/GameStateApi.g.cs";

/// `snake_case` as `PascalCase`.
fn pascal(s: &str) -> String {
    s.split('_')
        .map(|w| {
            let mut c = w.chars();
            c.next()
                .map(|f| f.to_ascii_uppercase().to_string() + c.as_str())
                .unwrap_or_default()
        })
        .collect()
}

/// A field type's C# type.
fn cs_type(ty: Ty) -> String {
    match ty {
        Ty::U8 => "byte".into(),
        Ty::U16 => "ushort".into(),
        Ty::U32 => "uint".into(),
        Ty::I16 => "short".into(),
        Ty::I32 => "int".into(),
        Ty::F32 => "float".into(),
        Ty::F64 => "double".into(),
        Ty::Bool => "bool".into(),
        Ty::Str => "string".into(),
        Ty::Bytes => "byte[]".into(),
        Ty::Vec3 => "Vector3".into(),
        Ty::Mat34 | Ty::Mat4 => "float[]".into(),
        Ty::Struct(s) => s().name.into(),
        Ty::List(s) => format!("List<{}>", s().name),
    }
}

/// A field's initial value (non-null for the reference types).
fn cs_init(ty: Ty) -> &'static str {
    match ty {
        Ty::Str => " = \"\";",
        Ty::Bytes => " = [];",
        Ty::Mat34 => " = new float[12];",
        Ty::Mat4 => " = new float[16];",
        Ty::Struct(_) | Ty::List(_) => " = new();",
        _ => ";",
    }
}

/// The reader's call for a field.
fn cs_read(ty: Ty) -> String {
    match ty {
        Ty::U8 => "r.U8()".into(),
        Ty::U16 => "r.U16()".into(),
        Ty::U32 => "r.U32()".into(),
        Ty::I16 => "r.I16()".into(),
        Ty::I32 => "r.I32()".into(),
        Ty::F32 => "r.F32()".into(),
        Ty::F64 => "r.F64()".into(),
        Ty::Bool => "r.Bool()".into(),
        Ty::Str => "r.Str()".into(),
        Ty::Bytes => "r.Bytes()".into(),
        Ty::Vec3 => "r.Vec3()".into(),
        Ty::Mat34 => "r.Floats(12)".into(),
        Ty::Mat4 => "r.Floats(16)".into(),
        Ty::Struct(s) => format!("{}.Read(ref r)", s().name),
        Ty::List(_) => unreachable!("lists are read in a loop"),
    }
}

/// `///` lines of a doc text.
fn doc(out: &mut String, indent: &str, text: &str) {
    let text = text.trim();
    if text.is_empty() {
        return;
    }
    let _ = writeln!(out, "{indent}/// <summary>");
    for line in text.lines() {
        let line = line
            .trim()
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;");
        let _ = writeln!(out, "{indent}/// {line}");
    }
    let _ = writeln!(out, "{indent}/// </summary>");
}

fn class(out: &mut String, s: &StructSchema) {
    doc(out, "", s.doc);
    let _ = writeln!(out, "public sealed partial class {}\n{{", s.name);
    for f in s.fields {
        doc(out, "    ", f.doc);
        let _ = writeln!(
            out,
            "    public {} {}{}",
            cs_type(f.ty),
            pascal(f.name),
            cs_init(f.ty)
        );
    }
    let _ = writeln!(
        out,
        "\n    /// <summary>Reads one from the encoding.</summary>\n    public static {0} Read(ref StateReader r)\n    {{\n        var o = new {0}();",
        s.name
    );
    for f in s.fields {
        let name = pascal(f.name);
        match f.ty {
            Ty::List(item) => {
                let item = item().name;
                let _ = writeln!(
                    out,
                    "        {{\n            int n = r.U16();\n            o.{name} = new List<{item}>(n);\n            for (int i = 0; i < n; i++)\n                o.{name}.Add({item}.Read(ref r));\n        }}"
                );
            }
            ty => {
                let _ = writeln!(out, "        o.{name} = {};", cs_read(ty));
            }
        }
    }
    let _ = writeln!(out, "        return o;\n    }}\n}}\n");
}

/// The generated C# file.
#[must_use]
pub fn generate() -> String {
    let mut out = format!(
        "// <auto-generated>\n// The game-state API's C# bindings, from ffx-rust's ffx-state (API {v}).\n// Generated by rust/ffx-state-cs (`cargo run -p ffx-state-cs`); do not edit.\n// </auto-generated>\n#nullable enable\nusing System;\nusing System.Collections.Generic;\nusing Godot;\n\nnamespace GdFfx.Api;\n\n/// <summary>The API's version and its decoder.</summary>\npublic static partial class StateApi\n{{\n    /// <summary>The API version these bindings decode.</summary>\n    public const uint Version = {v};\n\n    /// <summary>An encoded snapshot's first four bytes (<c>FFXS</c>).</summary>\n    public const uint Magic = 0x{m:08x};\n\n    /// <summary>Decodes a snapshot (<c>Snapshot::encode</c>'s bytes).</summary>\n    /// <exception cref=\"FormatException\">Not a snapshot, or another API version.</exception>\n    public static Snapshot Decode(ReadOnlySpan<byte> bytes)\n    {{\n        var r = new StateReader(bytes);\n        if (r.U32() != Magic)\n            throw new FormatException(\"not a game-state snapshot\");\n        var version = r.U32();\n        if (version != Version)\n            throw new FormatException($\"game-state API {{version}}, these bindings read {{Version}}\");\n        return Snapshot.Read(ref r);\n    }}\n}}\n\n",
        v = ffx_state::API_VERSION,
        m = ffx_state::MAGIC,
    );
    for s in ffx_state::structs() {
        class(&mut out, s);
    }
    out.truncate(out.trim_end().len());
    out.push('\n');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_bindings_are_current() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../godot/src/Api/GameStateApi.g.cs"
        );
        let committed = std::fs::read_to_string(path).unwrap_or_default();
        assert!(
            committed == generate(),
            "{path} is not what ffx-state's schema gives: run `cargo run -p ffx-state-cs`"
        );
    }

    #[test]
    fn names_and_types() {
        assert_eq!(pascal("previous_map"), "PreviousMap");
        assert_eq!(pascal("fov_y"), "FovY");
        let g = generate();
        assert!(g.contains("public List<Actor> Actors = new();"));
        assert!(g.contains("public Vector3 Position;"));
        assert!(g.contains("public float[] World = new float[12];"));
    }
}
